from fastapi import APIRouter, Depends, HTTPException, Query
import duckdb
import os

router = APIRouter(prefix="/analytics/lakehouse/metadata")

@router.get("/parquet-info")
async def inspect_parquet_file_metadata(
    file_path: str = Query(...),
    duck_conn: duckdb.DuckDBPyConnection = Depends(get_duckdb_session),
    current_user: User = Depends(get_current_user)
):
    normalized = os.path.normpath(file_path)
    allowed_dir = os.path.normpath(f"/mnt/lake/tenants/{current_user.tenant_id}")
    if not normalized.startswith(allowed_dir):
        raise HTTPException(status_code=403, detail="Forbidden: Path is outside tenant repository")

    try:
        query = "SELECT file_name, num_rows, num_row_groups, format_version FROM parquet_metadata(?)"
        df = duck_conn.execute(query, [normalized]).fetchdf()
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Metadata extraction failed: {str(e)}")

    return {"file": normalized, "metadata": df.to_dict(orient="records")}
